INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('1ae91949-feab-5f6f-b06f-8833d0520cbb', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 7, 7, 'Capacitors connected in parallel combine by the same rule as which resistor arrangement?', NULL, 1, 'multiple_choice'::answer_type, 'Resistors in series', NULL, false, NULL, false, NULL, 'C = C₁ + C₂ for parallel capacitors has the same form as R = R₁ + R₂ for series resistors. Mark scheme (1 mark). B1: C (Resistors in series).', 1, NULL, NULL),
('1b823314-adb4-547b-937a-3335e56cee12', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 8, 8, 'A 100 Ω resistor and a 220 Ω resistor are connected in series. Calculate the combined resistance.', NULL, 1, 'numeric'::answer_type, '320', 'Ω', false, NULL, false, NULL, 'R = R₁ + R₂ = 100 + 220 = 320 Ω. Mark scheme (2 marks). C1: resistances add in series. A1: R = 320 Ω.', 2, NULL, NULL),
('0eeababf-6fc7-5b94-83ae-bcfea77dd182', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 9, 9, 'A 100 µF capacitor and a 220 µF capacitor are connected in series. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '68.75', 'µF', false, NULL, false, ARRAY['6.875e-5']::text[], 'C = 100 × 220 ÷ (100 + 220) = 68.8 µF. Mark scheme (2 marks). C1: reciprocal rule for series capacitors. A1: C = 68.8 µF.', 2, NULL, NULL),
('2efc382a-8b8b-5369-99e9-501c46543873', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 10, 10, 'Which statement correctly compares a capacitor and a resistor in a d.c. circuit?', NULL, 1, 'multiple_choice'::answer_type, 'A capacitor stores energy; a resistor dissipates it as heat', NULL, false, NULL, false, NULL, 'Charge on the plates stores energy in the field; current through a resistor heats it. Mark scheme (1 mark). B1: A (A capacitor stores energy; a resistor dissipates it as heat).', 1, NULL, NULL),
('c2883c5c-1bdd-5a27-8e43-02d4635b9d5a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 11, 11, 'Two 10 kΩ resistors are connected in parallel. Calculate the combined resistance, in kΩ.', NULL, 1, 'numeric'::answer_type, '5', 'kΩ', false, NULL, false, ARRAY['5000']::text[], 'R = 10 × 10 ÷ (10 + 10) = 5.0 kΩ. Mark scheme (2 marks). C1: product over sum. A1: R = 5.0 kΩ.', 2, NULL, NULL),
('2a90eae7-26d0-5933-9aa3-7b4106155394', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 12, 12, 'A circuit uses two identical 10 µF capacitors side by side, connected in parallel. What capacitance, in µF, do they provide together?', NULL, 1, 'numeric'::answer_type, '20', 'µF', false, NULL, false, ARRAY['2e-5']::text[], 'Parallel capacitances add: C = 10 + 10 = 20 µF. Mark scheme (2 marks). C1: C = C₁ + C₂. A1: C = 20 µF.', 2, NULL, NULL),
('0055c075-33c4-5e15-9c28-0f6c5b4c5f3e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 13, 13, 'A capacitor in series with a resistor is connected to a battery and left for a long time. What is the current in the circuit?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'Once the capacitor is fully charged its p.d. equals the e.m.f., so there is no p.d. across the resistor and no current. Mark scheme (1 mark). B1: D (Zero).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 158" role="img" aria-labelledby="fg094120c7-t fg094120c7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg094120c7-t">Capacitor and resistor in series</title><desc id="fg094120c7-d">A capacitor in series with a resistor across a battery.</desc><line x1="26" y1="36" x2="70" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="36" x2="150" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="29" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="36" x2="207" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="274" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="24" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="24" x2="217" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="118" x2="145" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="118" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="105" x2="145" y2="131" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="111" x2="155" y2="125" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="36" x2="26" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="36" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A capacitor in series with a resistor across a battery.'),
('11d40fdb-885f-55ca-93b8-a2d6d110bb68', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 14, 14, 'Which quantity is the same for each component when resistors are in parallel, and also when capacitors are in parallel?', NULL, 1, 'multiple_choice'::answer_type, 'The p.d. across each component', NULL, false, NULL, false, NULL, 'Components in parallel are connected between the same two points. Mark scheme (1 mark). B1: B (The p.d. across each component).', 1, NULL, NULL),
('776b0bbe-4e74-5a40-929c-b6db95c0c1d0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 15, 15, 'What single resistor could replace three 30 Ω resistors wired side by side in parallel?', NULL, 1, 'numeric'::answer_type, '10', 'Ω', false, NULL, false, NULL, '1/R = 3/30, so R = 30 ÷ 3 = 10 Ω. Mark scheme (2 marks). C1: n equal resistors give R/n. A1: R = 10 Ω.', 2, NULL, NULL),
('0e69f5ae-d048-5b7b-9da6-16fb6844e87b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 16, 16, 'One more component is connected in parallel with an existing one. Which row is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Total resistance decreases for resistors; total capacitance increases for capacitors', NULL, false, NULL, false, NULL, 'An extra parallel path lowers resistance; extra plate area raises capacitance. Mark scheme (1 mark). B1: C (Total resistance decreases for resistors; total capacitance increases for capacitors).', 1, NULL, NULL),
('fc762ede-d8d0-53a7-a383-d416b25439f8', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 17, 17, 'A current of 0.50 A flows through a 20 Ω resistor for 10 s. Calculate the energy dissipated in the resistor.', NULL, 1, 'numeric'::answer_type, '50', 'J', false, NULL, false, NULL, 'W = I²Rt = 0.50² × 20 × 10 = 50 J. Mark scheme (2 marks). C1: W = I²Rt. A1: W = 50 J.', 2, NULL, NULL),
('7d4678da-6c43-5736-a8af-9aabc94c32d7', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 18, 18, 'Which pair of units is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Ω = V A⁻¹ and F = C V⁻¹', NULL, false, NULL, false, NULL, 'R = V/I and C = Q/V. Mark scheme (1 mark). B1: A (Ω = V A⁻¹ and F = C V⁻¹).', 1, NULL, NULL),
('7209764e-71fa-52f0-b190-2ec50153b88c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 19, 19, 'Three 4.7 µF capacitors are connected in series. Calculate their combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '1.567', 'µF', false, NULL, false, ARRAY['1.567e-6']::text[], 'C = 4.7 ÷ 3 = 1.57 µF. Mark scheme (2 marks). C1: n equal capacitors in series give C/n. A1: C = 1.57 µF.', 2, NULL, NULL),
('ba5a50da-cd27-58d4-86ad-cc7b54b2a065', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 20, 20, 'Which row shows the quantity that is the same for every component connected in series?', NULL, 1, 'multiple_choice'::answer_type, 'Resistors: current. Capacitors: charge.', NULL, false, NULL, false, NULL, 'The same current passes every series resistor; the same charge is moved onto every series capacitor. Mark scheme (1 mark). B1: D (Resistors: current. Capacitors: charge.).', 1, NULL, NULL),
('32ab50b6-13eb-5f45-bf38-a9cf9a2edfb3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 21, 21, 'A 1.0 kΩ resistor is joined end to end with another 1.0 kΩ resistor. What is the total resistance, in kΩ?', NULL, 1, 'numeric'::answer_type, '2', 'kΩ', false, NULL, false, ARRAY['2000']::text[], 'R = 1.0 + 1.0 = 2.0 kΩ. Mark scheme (1 mark). A1: R = 2.0 kΩ.', 1, NULL, NULL),
('569ba7c8-2f19-51b2-a884-8180778bea87', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 22, 22, 'Which statement about a capacitor and a resistor in a d.c. circuit is correct?', NULL, 1, 'multiple_choice'::answer_type, 'A steady current can pass through a resistor, but a capacitor stops a steady current once charged', NULL, false, NULL, false, NULL, 'The dielectric is an insulator, so current flows only while the capacitor''s charge is changing. Mark scheme (1 mark). B1: B (A steady current can pass through a resistor, but a capacitor stops a steady current once charged).', 1, NULL, NULL),
('49837286-1d5e-55b8-8953-68a5abc5189a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 23, 23, 'Calculate the combined capacitance of a 6.0 µF and a 3.0 µF capacitor in series, in µF. (It has the same value as 6.0 Ω and 3.0 Ω resistors in parallel, in Ω.)', NULL, 1, 'numeric'::answer_type, '2', 'µF', false, NULL, false, ARRAY['2e-6']::text[], 'C = 6.0 × 3.0 ÷ (6.0 + 3.0) = 2.0 µF. Mark scheme (2 marks). C1: product over sum. A1: C = 2.0 µF.', 2, NULL, NULL),
('6f4cfda7-4f45-59c9-bd16-79de48ee5718', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 24, 24, 'A 12 V battery charges a 470 µF capacitor through a 2.0 kΩ resistor. Calculate the charge on the capacitor after a long time, in mC.', NULL, 2, 'numeric'::answer_type, '5.64 mC', 'mC', false, NULL, false, NULL, 'When fully charged there is no current, so V_C = 12 V. Q = CV = 470 × 10⁻⁶ × 12 = 0.00564 C. In mC: 0.005640 × 1000 = 5.64. Mark scheme (3 marks). B1: no current so V_C = e.m.f. C1: Q = CV. A1: Q = 5.64 mC.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fgc05f7ea0-t fgc05f7ea0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc05f7ea0-t">Charging circuit</title><desc id="fgc05f7ea0-d">A 12 V battery charging a 470 µF capacitor through a 2.0 kΩ resistor.</desc><line x1="26" y1="48" x2="70" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 kΩ</text><line x1="150" y1="48" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="36" x2="207" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="217" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">470 µF</text><line x1="26" y1="142" x2="145" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="129" x2="145" y2="155" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="135" x2="155" y2="149" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 12 V battery charging a 470 µF capacitor through a 2.0 kΩ resistor.'),
('59499939-9370-5c98-b528-ebbfa76726b9', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 25, 25, 'A 1.0 kΩ and a 2.0 kΩ resistor are connected in series to a 9.0 V battery. A 100 µF capacitor is connected across the 2.0 kΩ resistor. Calculate the charge on the capacitor once the circuit has settled, in µC.', NULL, 2, 'numeric'::answer_type, '600 uC', 'µC', false, NULL, false, NULL, 'No current flows into the charged capacitor, so the resistors form a potential divider: V = 9.0 × 2.0 ÷ 3.0 = 6.0 V. Q = 100 × 10⁻⁶ × 6.0 = 6.0 × 10⁻⁴ C. In µC: 6.0 × 10⁻⁴ × 10⁶ = 600. Mark scheme (3 marks). C1: potential divider. C1: Q = CV. A1: Q = 600 µC.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg52a96b6d-t fg52a96b6d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg52a96b6d-t">Capacitor across a resistor</title><desc id="fg52a96b6d-d">A 9.0 V battery with a 1.0 kΩ resistor in series with a 2.0 kΩ resistor; a 100 µF capacitor is connected across the 2.0 kΩ resistor.</desc><line x1="26" y1="48" x2="62" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="62" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 kΩ</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="186" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="186" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 kΩ</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">9.0 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 9.0 V battery with a 1.0 kΩ resistor in series with a 2.0 kΩ resistor; a 100 µF capacitor is connected across the 2.0 kΩ resistor.'),
('1a3083f6-5170-5e87-9b61-06916e4e14c2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 26, 26, 'A capacitor and resistor in series are connected to a battery. A long time later, what are the p.d.s across them?', NULL, 2, 'multiple_choice'::answer_type, 'Capacitor: equal to the e.m.f. Resistor: zero.', NULL, false, NULL, false, NULL, 'With no current, V_R = IR = 0, so all the e.m.f. appears across the capacitor. Mark scheme (3 marks). C1: I = 0 when charged. C1: V_C = e.m.f. A1: C (Capacitor: equal to the e.m.f. Resistor: zero.).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 158" role="img" aria-labelledby="fgd8e253ea-t fgd8e253ea-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd8e253ea-t">Capacitor and resistor in series</title><desc id="fgd8e253ea-d">A capacitor in series with a resistor connected to a battery.</desc><line x1="26" y1="36" x2="70" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="36" x2="150" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="29" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="36" x2="207" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="274" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="24" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="24" x2="217" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="118" x2="145" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="118" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="105" x2="145" y2="131" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="111" x2="155" y2="125" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="36" x2="26" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="36" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A capacitor in series with a resistor connected to a battery.'),
('539f519a-7c0c-5305-a1d5-f7865881fd40', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 27, 27, 'A 3.0 µF and a 6.0 µF capacitor are connected in series across 12 V. Separately, 3.0 Ω and 6.0 Ω resistors are connected in parallel across 12 V. Calculate the charge on each capacitor, in µC.', NULL, 2, 'numeric'::answer_type, '24 uC', 'µC', false, NULL, false, NULL, 'Series capacitors: C = 3.0 × 6.0 ÷ 9.0 = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. In µC: 2.4 × 10⁻⁵ × 10⁶ = 24. (The resistors give R = 2.0 Ω and I = 6.0 A: the same number, by the same rule.). Mark scheme (4 marks). C1: reciprocal rule for capacitors. C1: Q = CV. B1: same form as parallel resistors. A1: Q = 24 µC.', 4, NULL, NULL),
('e016685f-66bf-5648-992e-9b9cf10cf13b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 28, 28, 'A 100 µF capacitor charged to 10 V stores some energy. A 1.0 kΩ resistor connected across a 10 V supply dissipates energy steadily. How long does the resistor take to dissipate the same energy as the capacitor stores?', NULL, 2, 'numeric'::answer_type, '0.05', 's', false, NULL, false, NULL, 'W = 0.5 × 100 × 10⁻⁶ × 10² = 5.0 × 10⁻³ J. P = V²/R = 10² ÷ 1000 = 0.10 W. t = 5.0 × 10⁻³ ÷ 0.10 = 0.050 s. Mark scheme (3 marks). C1: W = ½CV². C1: P = V²/R. C1: t = W/P.', 3, NULL, NULL),
('7935afba-7d52-5acd-bf92-1c958c84cc89', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 29, 29, 'The plates of a parallel-plate capacitor are made twice as large in area. The cross-sectional area of a resistance wire is also doubled. Which row is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Capacitance doubles; resistance halves', NULL, false, NULL, false, NULL, 'C = εA/d ∝ A; R = ρL/A ∝ 1/A. Mark scheme (3 marks). C1: C ∝ A. C1: R ∝ 1/A. A1: A (Capacitance doubles; resistance halves).', 3, NULL, NULL),
('e964d211-1afa-5989-994f-4fde3cdcfde3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 30, 30, 'A 1.5 kΩ resistor and an uncharged capacitor are connected in parallel directly across a 6.0 V battery of negligible internal resistance. Calculate the current in the resistor once the capacitor has charged, in mA.', NULL, 2, 'numeric'::answer_type, '4 mA', 'mA', false, NULL, false, NULL, 'The resistor always has the full 6.0 V across it: I = V/R = 6.0 ÷ 1500 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (3 marks). C1: same p.d. in parallel. C1: I = V/R. A1: I = 4.0 mA.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 224" role="img" aria-labelledby="fg3c5432c7-t fg3c5432c7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3c5432c7-t">Resistor and capacitor in parallel</title><desc id="fg3c5432c7-d">A 1.5 kΩ resistor and an uncharged capacitor in parallel directly across a 6.0 V battery.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="132" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="132" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5 kΩ</text><line x1="42" y1="90" x2="145" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="90" x2="258" y2="90" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="78" x2="145" y2="102" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="78" x2="155" y2="102" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="184" x2="145" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="184" x2="274" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="171" x2="145" y2="197" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="177" x2="155" y2="191" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="208" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 V</text><line x1="26" y1="48" x2="26" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="184" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 1.5 kΩ resistor and an uncharged capacitor in parallel directly across a 6.0 V battery.'),
('99d30a43-ddde-57bc-a1ad-9f39bc56d513', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 31, 31, 'Three identical capacitors are to be connected together. Which arrangement gives the largest combined capacitance?', NULL, 2, 'multiple_choice'::answer_type, 'All three in parallel', NULL, false, NULL, false, NULL, 'Parallel gives 3C; the others give C/3, 1.5C and 2C/3. Mark scheme (4 marks). C1: parallel adds. C1: series reduces. C1: compares all four. A1: D (All three in parallel).', 4, NULL, NULL),
('4c57997a-a90b-53c2-a686-fb44e5833df5', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 32, 32, 'A 2.0 µF capacitor is connected in series with two 4.0 µF capacitors that are in parallel with each other. Calculate the combined capacitance, in µF. (2.0 Ω, 4.0 Ω and 4.0 Ω resistors arranged the same way would give 4.0 Ω.)', NULL, 2, 'numeric'::answer_type, '1.6', 'µF', false, NULL, false, ARRAY['1.6e-6']::text[], 'Parallel pair: 4.0 + 4.0 = 8.0 µF. With 2.0 µF in series: C = 2.0 × 8.0 ÷ 10 = 1.6 µF. Mark scheme (3 marks). C1: parallel pair first. C1: series with 2.0 µF. A1: C = 1.6 µF.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 270 146" role="img" aria-labelledby="fgaf76523a-t fgaf76523a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaf76523a-t">Capacitor network</title><desc id="fgaf76523a-d">Between terminals A and B: a 2.0 µF capacitor in series with two 4.0 µF capacitors in parallel.</desc><line x1="40" y1="50" x2="67" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="77" y1="50" x2="104" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="67" y1="38" x2="67" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="77" y1="38" x2="77" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="72" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 µF</text><line x1="104" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="147" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="50" x2="184" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="38" x2="147" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="38" x2="157" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="152" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><line x1="120" y1="104" x2="147" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="104" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="92" x2="147" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="92" x2="157" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="152" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><circle cx="120" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="184" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="222" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="222" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text></svg>', 'Between terminals A and B: a 2.0 µF capacitor in series with two 4.0 µF capacitors in parallel.'),
('d0d1c03f-3814-567d-9a53-3af2ed26d065', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 33, 33, 'A 5.0 V supply is connected across a 1.0 kΩ resistor in series with a 3.3 kΩ resistor. A 10 µF capacitor is connected in parallel with the 3.3 kΩ resistor. Calculate the charge on the capacitor once the circuit has settled, in µC.', NULL, 2, 'numeric'::answer_type, '38.37 uC', 'µC', false, NULL, false, NULL, 'No current enters the charged capacitor, so I = 5.0 ÷ 4300 = 0.00116 A and V = 5.0 × 3.3 ÷ 4.3 = 3.84 V. Q = 10 × 10⁻⁶ × 3.837 = 3.84 × 10⁻⁵ C. In µC: 3.837 × 10⁻⁵ × 10⁶ = 38.4. Mark scheme (4 marks). B1: capacitor branch carries no steady current. C1: p.d. across 3.3 kΩ. C1: Q = CV. A1: Q = 38.4 µC.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg56679c47-t fg56679c47-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg56679c47-t">Capacitor across a resistor</title><desc id="fg56679c47-d">A 5.0 V supply across a 1.0 kΩ resistor in series with a 3.3 kΩ resistor; a 10 µF capacitor is connected in parallel with the 3.3 kΩ resistor.</desc><line x1="26" y1="48" x2="62" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="62" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 kΩ</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="186" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="186" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.3 kΩ</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 5.0 V supply across a 1.0 kΩ resistor in series with a 3.3 kΩ resistor; a 10 µF capacitor is connected in parallel with the 3.3 kΩ resistor.'),
('da0735fc-84af-59a3-bec4-e0ae056b96c0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 34, 34, 'An uncharged capacitor in series with a resistor is switched onto a battery. What are the p.d.s immediately after the switch is closed?', NULL, 2, 'multiple_choice'::answer_type, 'Capacitor: zero. Resistor: equal to the e.m.f.', NULL, false, NULL, false, NULL, 'A capacitor''s p.d. depends on its charge, which cannot change instantly; at first all the e.m.f. is across R. Mark scheme (3 marks). C1: V_C = Q/C = 0 initially. C1: V_R = e.m.f. A1: B (Capacitor: zero. Resistor: equal to the e.m.f.).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 158" role="img" aria-labelledby="fgb95704ab-t fgb95704ab-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb95704ab-t">Switching on</title><desc id="fgb95704ab-d">An uncharged capacitor in series with a resistor, a battery and an open switch.</desc><line x1="26" y1="36" x2="70" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="36" x2="150" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="29" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="36" x2="207" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="274" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="24" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="24" x2="217" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="118" x2="83" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="118" x2="150" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="105" x2="83" y2="131" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="111" x2="93" y2="125" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="118" x2="198" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="118" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="198" cy="118" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="226" cy="118" r="2.6" style="fill:currentColor;stroke:none"/><line x1="198" y1="118" x2="224" y2="106" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="36" x2="26" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="36" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'An uncharged capacitor in series with a resistor, a battery and an open switch.'),
('d2362a73-6f06-5b58-9c75-4dcc65efa269', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 35, 35, 'An uncharged capacitor is connected in series with a 4.7 kΩ resistor to a 12 V battery. Calculate the charging current at the instant the switch is closed, in mA.', NULL, 2, 'numeric'::answer_type, '2.553 mA', 'mA', false, NULL, false, NULL, 'Initially V_C = 0, so all 12 V is across the resistor: I = 12 ÷ 4700 = 0.00255 A. In mA: 0.002553 × 1000 = 2.55. Mark scheme (4 marks). B1: V_C = 0 at the start. C1: I = V/R. C1: conversion to mA. A1: I = 2.55 mA.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fg3cee8a96-t fg3cee8a96-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3cee8a96-t">Charging circuit</title><desc id="fg3cee8a96-d">An uncharged capacitor in series with a 4.7 kΩ resistor, a 12 V battery and a switch.</desc><line x1="26" y1="48" x2="70" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.7 kΩ</text><line x1="150" y1="48" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="36" x2="207" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="217" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="142" x2="83" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="142" x2="150" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="129" x2="83" y2="155" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="135" x2="93" y2="149" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="150" y1="142" x2="198" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="198" cy="142" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="226" cy="142" r="2.6" style="fill:currentColor;stroke:none"/><line x1="198" y1="142" x2="224" y2="130" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'An uncharged capacitor in series with a 4.7 kΩ resistor, a 12 V battery and a switch.'),
('7a59ad22-774d-5812-9627-ef2c143cb391', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 36, 36, 'Which pair of combinations both give a total that is smaller than any single component?', NULL, 2, 'multiple_choice'::answer_type, 'Capacitors in series and resistors in parallel', NULL, false, NULL, false, NULL, 'Both use the reciprocal-sum rule, which always gives less than the smallest value. Mark scheme (3 marks). C1: reciprocal rule. C1: identifies both cases. A1: C (Capacitors in series and resistors in parallel).', 3, NULL, NULL),
('37d372b8-0eac-53e4-adb9-9d2bc593f8b2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 37, 37, 'How many 1.0 kΩ resistors must be connected in parallel to give a combined resistance of 250 Ω?', NULL, 2, 'numeric'::answer_type, '4', NULL, false, NULL, false, NULL, 'n equal resistors in parallel give R/n, so n = 1000 ÷ 250 = 4. Mark scheme (3 marks). C1: R_total = R/n. C1: rearranged. A1: n = 4.', 3, NULL, NULL),
('9614b248-2111-57d9-9f1a-684118d18945', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 38, 38, 'A 2200 µF capacitor is charged to 12 V through a resistor by a 12 V battery. Calculate the energy dissipated in the resistor.', NULL, 2, 'numeric'::answer_type, '0.1584', 'J', false, NULL, false, NULL, 'The battery supplies QV = CV² and the capacitor stores ½CV², so the resistor dissipates the other half: 0.5 × 2200 × 10⁻⁶ × 12² = 0.158 J. Mark scheme (3 marks). M1: energy dissipated = ½CV². C1: substitution. A1: W = 0.158 J.', 3, NULL, NULL),
('e6b048e1-ca98-5acf-97db-fadd0696375b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 39, 39, 'Why does a steady current stop in a capacitor branch of a d.c. circuit, but not in a resistor branch?', NULL, 2, 'multiple_choice'::answer_type, 'The capacitor''s dielectric is an insulator, so charge builds up on its plates until their p.d. opposes the supply', NULL, false, NULL, false, NULL, 'Charge cannot cross the dielectric; current only flows while the plates are charging. Mark scheme (3 marks). C1: insulating dielectric. C1: build-up of p.d. opposes supply. A1: A (The capacitor''s dielectric is an insulator, so charge builds up on its plates until their p.d. opposes the supply).', 3, NULL, NULL),
('246774a3-1c0a-57e0-905b-c5db30cebf5e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 40, 40, 'A 6.0 µF and a 3.0 µF capacitor in series are connected across 9.0 V. Separately, a 6.0 Ω and a 3.0 Ω resistor in series are connected across 9.0 V. Calculate the p.d. across the 6.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '3', 'V', false, NULL, false, NULL, 'Same charge on each capacitor, so V ∝ 1/C: V₆ = 9.0 × 3.0 ÷ (6.0 + 3.0) = 3.0 V. (The 6.0 Ω resistor takes 6.0 V instead: for resistors V ∝ R.). Mark scheme (4 marks). C1: same Q. M1: V ∝ 1/C. B1: contrast with V ∝ R. A1: V = 3.0 V.', 4, NULL, NULL),
('1f1384b9-1d65-5c10-8881-0070fb2ab349', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 41, 41, 'A 12 V battery is connected across a 2.0 kΩ resistor R₁ in series with a 4.0 kΩ resistor R₂. A 10 µF capacitor is connected across R₁ and a 20 µF capacitor across R₂. (a) Explain why no current flows into either capacitor once the circuit has settled. (b) Calculate the p.d. across each capacitor. (c) Calculate the charge on the 20 µF capacitor, in µC. (d) Calculate the total energy stored. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '160 uC', 'µC', false, NULL, false, NULL, '(a) Once charged, the capacitors'' p.d.s equal those across the resistors, and no charge can cross a dielectric. (b) I = 12 ÷ 6000 = 2.0 × 10⁻³ A; V₁ = 2.0 × 10⁻³ × 2000 = 4.0 V and V₂ = 2.0 × 10⁻³ × 4000 = 8.0 V. (c) Q = 20 × 10⁻⁶ × 8.0 = 1.6 × 10⁻⁴ C. In µC: 1.6 × 10⁻⁴ × 10⁶ = 160. (d) W = 0.5 × 10 × 10⁻⁶ × 4.0² + 0.5 × 20 × 10⁻⁶ × 8.0² = 7.2 × 10⁻⁴ J. Mark scheme (6 marks). B1: no steady current into capacitors. C1: potential divider. C1: V across each. C1: Q = CV. C1: total energy. A1: Q = 160 µC.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg8fdb752c-t fg8fdb752c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8fdb752c-t">Capacitors across resistors</title><desc id="fg8fdb752c-d">A 12 V battery across R₁ = 2.0 kΩ in series with R₂ = 4.0 kΩ; a 10 µF capacitor is connected across R₁ and a 20 µF capacitor across R₂.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="134" y1="48" x2="134" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="70" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">R₁ = 2.0 kΩ</text><line x1="42" y1="102" x2="83" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="102" x2="134" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="90" x2="83" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="90" x2="93" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="134" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="150" y1="48" x2="166" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166" y1="48" x2="166" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166" y1="48" x2="194" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="194" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">R₂ = 4.0 kΩ</text><line x1="166" y1="102" x2="207" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="90" x2="207" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="90" x2="217" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20 µF</text><circle cx="166" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 12 V battery across R₁ = 2.0 kΩ in series with R₂ = 4.0 kΩ; a 10 µF capacitor is connected across R₁ and a 20 µF capacitor across R₂.'),
('944daafe-207d-5eaa-8066-3e6b5dfeb0ab', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 42, 42, 'Three components, each of value 6.0 (6.0 Ω for resistors or 6.0 µF for capacitors), are connected with two in parallel and that pair in series with the third. (a) Calculate the combined resistance for three resistors. (b) Calculate the combined capacitance for three capacitors, in µF. (c) Explain why the two answers are different although the arrangement is the same. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], '(a) Parallel pair 3.0 Ω, in series with 6.0 Ω: R = 3.0 + 6.0 = 9.0 Ω. (b) Parallel pair 12 µF, in series with 6.0 µF: C = 12 × 6.0 ÷ 18 = 4.0 µF. (c) The rules are reversed: capacitors add in parallel but resistors add in series. Mark scheme (5 marks). C1: resistor network. C1: parallel capacitors add. C1: series capacitors by reciprocal rule. B1: rules swapped for C and R. A1: C = 4.0 µF.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 270 296" role="img" aria-labelledby="fg47758cfb-t fg47758cfb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg47758cfb-t">Resistors and capacitors compared</title><desc id="fg47758cfb-d">Two networks between terminals A and B: two 6.0 Ω resistors in parallel in series with a third 6.0 Ω resistor; and two 6.0 µF capacitors in parallel in series with a third 6.0 µF capacitor.</desc><g transform="translate(0,0)"><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="136" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="70" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="43" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 Ω</text><line x1="56" y1="104" x2="70" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="104" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="97" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 Ω</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="120" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="136" y1="50" x2="150" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="186" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="150" y="43" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="168" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 Ω</text><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="222" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="222" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text></g><g transform="translate(0,150)"><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="136" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="83" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="38" x2="83" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="38" x2="93" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 µF</text><line x1="56" y1="104" x2="83" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="104" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="92" x2="83" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="92" x2="93" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 µF</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="120" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="136" y1="50" x2="163" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="173" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="163" y1="38" x2="163" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="173" y1="38" x2="173" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="168" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 µF</text><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="222" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="222" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text></g></svg>', 'Two networks between terminals A and B: two 6.0 Ω resistors in parallel in series with a third 6.0 Ω resistor; and two 6.0 µF capacitors in parallel in series with a third 6.0 µF capacitor.'),
('584b189b-2e3d-51ca-9048-bdab80b1a094', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 43, 43, 'A 470 µF capacitor is charged from 0 to 9.0 V through a resistor R by a 9.0 V battery. (a) Calculate the energy supplied by the battery. (b) Calculate the energy stored in the capacitor. (c) Calculate the energy dissipated in the resistor, in mJ. (d) Explain why the answer to (c) does not depend on the value of R. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '19.04 mJ', 'mJ', false, NULL, false, NULL, '(a) Q = 470 × 10⁻⁶ × 9.0 = 0.00423 C; W = QV = 0.004230 × 9.0 = 0.0381 J. (b) ½QV = 0.5 × 0.004230 × 9.0 = 0.0190 J. (c) 0.03807 − 0.01903 = 0.0190 J. In mJ: 0.01903 × 1000 = 19.0. (d) The same charge passes through R whatever its value; R only changes how quickly the charging happens. Mark scheme (6 marks). C1: W = QV from battery. C1: ½QV stored. M1: difference dissipated. C1: conversion to mJ. B1: independent of R, only time changes. A1: W = 19.0 mJ.', 6, NULL, NULL),
('9e53daa4-9c76-5855-8df6-186ae695a051', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 44, 44, 'A 6.0 V battery is connected across two parallel branches. Branch 1 is a 1.0 kΩ resistor in series with a 2.0 kΩ resistor, with the 2.0 kΩ resistor connected to the negative terminal. Branch 2 is a 2.0 µF capacitor in series with a 4.0 µF capacitor, with the 4.0 µF capacitor connected to the negative terminal. A high-resistance voltmeter is connected between the midpoints of the two branches. (a) Calculate the p.d. across the 2.0 kΩ resistor. (b) Calculate the p.d. across the 4.0 µF capacitor. (c) Calculate the voltmeter reading. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2', 'V', false, NULL, false, NULL, '(a) Potential divider: 6.0 × 2.0 ÷ 3.0 = 4.0 V. (b) Same charge on both capacitors, so V ∝ 1/C: 6.0 × 2.0 ÷ (2.0 + 4.0) = 2.0 V. (c) The midpoints are 4.0 V and 2.0 V above the negative terminal: reading = 4.0 − 2.0 = 2.0 V. Mark scheme (6 marks). C1: resistor divider V ∝ R. M1: capacitor divider V ∝ 1/C. C1: p.d. across 4.0 µF. C1: difference of potentials. B1: explains which side is higher. A1: V = 2.0 V.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fgd3300307-t fgd3300307-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd3300307-t">Resistor and capacitor branches</title><desc id="fgd3300307-d">A 6.0 V battery across two parallel branches: a 1.0 kΩ resistor in series with a 2.0 kΩ resistor, and a 2.0 µF capacitor in series with a 4.0 µF capacitor.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="78" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="114" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="78" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="96" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 kΩ</text><line x1="150" y1="48" x2="186" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="186" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 kΩ</text><line x1="42" y1="102" x2="91" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101" y1="102" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="91" y1="90" x2="91" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101" y1="90" x2="101" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="96" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 6.0 V battery across two parallel branches: a 1.0 kΩ resistor in series with a 2.0 kΩ resistor, and a 2.0 µF capacitor in series with a 4.0 µF capacitor.'),
('b3306901-30d8-512b-82bd-be205ae364b4', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 45, 45, 'A real 100 µF capacitor can be modelled as an ideal capacitor in parallel with a 10 MΩ "leakage" resistance. It is charged to 12 V and disconnected. (a) Calculate the initial leakage current, in µA. (b) Calculate the initial charge. (c) Estimate the time for the capacitor to lose 1 % of its charge, assuming the current stays roughly constant. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '1.2 uA', 'µA', false, NULL, false, NULL, '(a) I = V/R = 12 ÷ 10 × 10⁶ = 1.2 × 10⁻⁶ A. In µA: 1.2 × 10⁻⁶ × 10⁶ = 1.2. (b) Q = 100 × 10⁻⁶ × 12 = 1.2 × 10⁻³ C. (c) 1 % of Q = 1.2 × 10⁻⁵ C; t = 1.2 × 10⁻⁵ ÷ 1.2 × 10⁻⁶ = 10 s. Mark scheme (5 marks). C1: I = V/R. C1: Q = CV. C1: 1 % of Q. C1: t = ΔQ/I. A1: I = 1.2 µA.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 257.1 146" role="img" aria-labelledby="fg9a9411a1-t fg9a9411a1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9a9411a1-t">Leaky capacitor model</title><desc id="fg9a9411a1-d">Model of a real capacitor between terminals A and B: an ideal 100 µF capacitor in parallel with a 10 MΩ leakage resistance.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="171.1" y1="50" x2="187.1" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="171.1" y1="50" x2="171.1" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="108.6" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="118.6" y1="50" x2="171.1" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="108.6" y1="38" x2="108.6" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="118.6" y1="38" x2="118.6" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="113.6" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100 µF</text><line x1="56" y1="104" x2="95.6" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="131.6" y1="104" x2="171.1" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="95.6" y="97" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="113.6" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 MΩ leakage</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="171.1" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="209.1" y1="50" x2="187.1" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="209.1" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="219.1" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text></svg>', 'Model of a real capacitor between terminals A and B: an ideal 100 µF capacitor in parallel with a 10 MΩ leakage resistance.'),
('516905b7-651a-5921-b745-beca99a0f905', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 46, 46, 'A 2.0 µF and an 8.0 µF capacitor are connected in series across a 100 V supply. (a) Calculate the p.d. across each capacitor. (b) A 1.0 MΩ resistor is now connected in parallel with each capacitor. Explain why, after a long time, the p.d.s become 50 V each. (c) Calculate the charge on the 2.0 µF capacitor in this new steady state, in µC. Give only the p.d. across the 2.0 µF capacitor from (a).', NULL, 3, 'numeric'::answer_type, '80', 'V', false, NULL, false, NULL, '(a) Same charge, so V ∝ 1/C: V₂ = 100 × 8.0 ÷ (2.0 + 8.0) = 80 V and V₈ = 20 V. (b) In the steady state a current flows through the two equal resistors, which share the 100 V equally, and each capacitor takes the p.d. of the resistor across it. (c) Q = 2.0 × 10⁻⁶ × 50 = 1.0 × 10⁻⁴ C, which is 100 µC. Mark scheme (6 marks). M1: V ∝ 1/C in series. C1: 80 V and 20 V. B1: resistors set the steady p.d.s. B1: equal resistors share equally. C1: Q = CV. A1: V = 80 V.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fgde9d3c25-t fgde9d3c25-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgde9d3c25-t">Capacitors in series</title><desc id="fgde9d3c25-d">A 2.0 µF and an 8.0 µF capacitor in series across a 100 V supply.</desc><line x1="26" y1="48" x2="83" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="36" x2="83" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="36" x2="93" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 µF</text><line x1="150" y1="48" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="36" x2="207" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="217" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0 µF</text><line x1="26" y1="142" x2="145" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="129" x2="145" y2="155" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="135" x2="155" y2="149" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">100 V</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 2.0 µF and an 8.0 µF capacitor in series across a 100 V supply.'),
('a72093a3-9d26-546a-8a65-3748d727e801', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 47, 47, 'A battery of e.m.f. 12 V and internal resistance 0.50 Ω is connected to a 5.5 Ω resistor. A 1000 µF capacitor is connected directly across the battery terminals. (a) Calculate the current. (b) Calculate the terminal p.d. (c) Calculate the charge on the capacitor, in mC. (d) State the charge on the capacitor if the 5.5 Ω resistor were removed. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '11 mC', 'mC', false, NULL, false, NULL, '(a) I = 12 ÷ (5.5 + 0.50) = 2.0 A. (b) V = 12 − 2.0 × 0.50 = 11 V. (c) Q = 1000 × 10⁻⁶ × 11 = 0.011 C. In mC: 0.011 × 1000 = 11. (d) With no current, V = e.m.f. = 12 V, so Q = 12 mC. Mark scheme (5 marks). C1: I = E/(R + r). C1: terminal p.d. C1: Q = CV. B1: 12 mC with no current. A1: Q = 11 mC.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg8e983500-t fg8e983500-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8e983500-t">Capacitor across the battery</title><desc id="fg8e983500-d">A battery of e.m.f. 12 V and internal resistance 0.50 Ω connected to a 5.5 Ω resistor, with a 1000 µF capacitor directly across the battery terminals.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="132" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="132" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.5 Ω</text><line x1="42" y1="102" x2="145" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="90" x2="145" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="90" x2="155" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1000 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="78" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="196" x2="140.1" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="78" y1="183" x2="78" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="88" y1="189" x2="88" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="83" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="140.1" y1="196" x2="189" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="225" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="189" y="189" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="207" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">r = 0.50 Ω</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A battery of e.m.f. 12 V and internal resistance 0.50 Ω connected to a 5.5 Ω resistor, with a 1000 µF capacitor directly across the battery terminals.'),
('79407b12-670f-577b-bc0e-1e3134b75fa8', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 48, 48, 'An uncharged 47 µF capacitor is connected in series with a 10 kΩ resistor to a 9.0 V battery. (a) Calculate the initial current. (b) Calculate the initial rate at which the p.d. across the capacitor rises, in V s⁻¹. (c) Explain why this rate decreases as the capacitor charges. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '19.15', 'V s⁻¹', false, NULL, false, NULL, '(a) I₀ = 9.0 ÷ 10 000 = 9.0 × 10⁻⁴ A. (b) I = dQ/dt = C dV/dt, so dV/dt = 9.0 × 10⁻⁴ ÷ 47 × 10⁻⁶ = 19.1 V s⁻¹. (c) As V_C rises, the p.d. across the resistor and hence the current fall, so charge, and p.d., are added more slowly. Mark scheme (6 marks). C1: I₀ = E/R. M1: I = C dV/dt. C1: substitution. B1: current falls as V_C rises. C1: units V s⁻¹. A1: dV/dt = 19.1 V s⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fg4269cb02-t fg4269cb02-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4269cb02-t">Charging circuit</title><desc id="fg4269cb02-d">An uncharged 47 µF capacitor in series with a 10 kΩ resistor, a 9.0 V battery and a switch.</desc><line x1="26" y1="48" x2="70" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="106" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="70" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 kΩ</text><line x1="150" y1="48" x2="207" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="36" x2="207" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="36" x2="217" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">47 µF</text><line x1="26" y1="142" x2="83" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="142" x2="150" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="129" x2="83" y2="155" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="135" x2="93" y2="149" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">9.0 V</text><line x1="150" y1="142" x2="198" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="198" cy="142" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="226" cy="142" r="2.6" style="fill:currentColor;stroke:none"/><line x1="198" y1="142" x2="224" y2="130" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'An uncharged 47 µF capacitor in series with a 10 kΩ resistor, a 9.0 V battery and a switch.'),
('a0153e3a-9fb4-52f7-9da4-1d6f315a41df', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 49, 49, '(a) Explain why resistances add in series but capacitances add in parallel, by stating what is common to the components in each case. (b) Calculate the combined resistance of 3.3 kΩ and 4.7 kΩ resistors in series. (c) Calculate the combined capacitance of 3.3 µF and 4.7 µF capacitors in series, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '1.939', 'µF', false, NULL, false, ARRAY['1.939e-6']::text[], '(a) Series resistors carry the same current and their p.d.s add, so R = V/I adds. Parallel capacitors share the same p.d. and their charges add, so C = Q/V adds. (b) R = 3.3 + 4.7 = 8.0 kΩ. (c) C = 3.3 × 4.7 ÷ (3.3 + 4.7) = 1.94 µF. Mark scheme (5 marks). B1: common current in series resistors. B1: common p.d. in parallel capacitors. C1: series resistance. C1: series capacitance. A1: C = 1.94 µF.', 5, NULL, NULL),
('bd54c6c6-564d-580e-a9c8-cdf9c00a96b3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '37b002d3-71bb-4659-b130-a879ad127cf8', 'a-level', '23.5', '9702 coursebook 23.5 · Comparing capacitors and resistors', 50, 50, 'A 12 V battery is connected in series with a 10 kΩ resistor to a 220 µF capacitor. A 20 kΩ resistor is connected in parallel with the capacitor. (a) Explain why a steady current still flows when the capacitor is fully charged. (b) Calculate this steady current. (c) Calculate the final p.d. across the capacitor. (d) Calculate the final charge on the capacitor, in mC. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '1.76 mC', 'mC', false, NULL, false, NULL, '(a) Current can still pass through the 20 kΩ resistor, which is a parallel path around the capacitor. (b) I = 12 ÷ 30 000 = 4.0 × 10⁻⁴ A. (c) V = 4.0 × 10⁻⁴ × 20 000 = 8.0 V. (d) Q = 220 × 10⁻⁶ × 8.0 = 1.76 × 10⁻³ C. In mC: 1.76 × 10⁻³ × 1000 = 1.76. Mark scheme (6 marks). B1: path through parallel resistor. C1: I = E/R_total. C1: V across 20 kΩ. C1: Q = CV. C1: conversion to mC. A1: Q = 1.76 mC.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fgfc36758a-t fgfc36758a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfc36758a-t">Charging with a parallel resistor</title><desc id="fgfc36758a-d">A 12 V battery in series with a 10 kΩ resistor and a 220 µF capacitor; a 20 kΩ resistor is connected in parallel with the capacitor.</desc><line x1="26" y1="48" x2="62" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="62" y="41" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 kΩ</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">220 µF</text><line x1="150" y1="102" x2="186" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="222" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="186" y="95" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20 kΩ</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 12 V battery in series with a 10 kΩ resistor and a 220 µF capacitor; a 20 kΩ resistor is connected in parallel with the capacitor.')
