('946bb76a-8536-5d95-a7af-bf19921efeaa', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 8, 8, 'A branch of two 4.0 µF capacitors in series has a 2.0 µF capacitor connected across it. What is the total, in µF?', NULL, 1, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], 'Series pair: 4.0 ÷ 2 = 2.0 µF. In parallel with 2.0 µF: C = 2.0 + 2.0 = 4.0 µF. Mark scheme (2 marks). C1: series pair then parallel. A1: C = 4.0 µF.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 270 146" role="img" aria-labelledby="fg5cccf942-t fg5cccf942-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5cccf942-t">Capacitor network</title><desc id="fg5cccf942-d">Between A and B: two 4.0 µF capacitors in series, with a 2.0 µF capacitor connected across the pair.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="83" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="38" x2="83" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="38" x2="93" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><line x1="120" y1="50" x2="147" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="50" x2="184" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="38" x2="147" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="38" x2="157" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="152" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><line x1="56" y1="104" x2="115" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="104" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="92" x2="115" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="92" x2="125" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="120" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 µF</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="184" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38"