('a65123eb-042f-5495-9153-1df7a1aaffba', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 9, 9, 'What is the best first step when finding the combined capacitance of a network?', NULL, 1, 'multiple_choice'::answer_type, 'Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor', NULL, false, NULL, false, NULL, 'Simplify the innermost groups step by step until one capacitor remains. Mark scheme (1 mark). B1: C (Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor).', 1, NULL, NULL),
('aff7b284-e6da-572f-a2d4-afddffcefe4e', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 10, 10, 'Three 3.0 µF capacitors are connected so that two are in series and that pair is in parallel with the third. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '4.5', 'µF', false, NULL, false, ARRAY['4.5e-6']::text[], 'Series pair: 3.0 ÷ 2 = 1.5 µF. Total: 1.5 + 3.0 = 4.5 µF. Mark scheme (2 marks). C1: series pair then add. A1: C = 4.5 µF.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 270 146" role="img" aria-labelledby="fg69332352-t fg69332352-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg69332352-t">Capacitor network</title><desc id="fg69332352-d">Between A and B: two 3.0 µF capacitors in series, in parallel with a third 3.0 µF capacitor.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="83" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="38" x2="83" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="38" x2="93" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><line x1="120" y1="50" x2="147" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="50" x2="184" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="38" x2="147" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="38" x2="157" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="152" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><line x1="56" y1="104" x2="115" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="104" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="92" x2="115" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="92" x2="125" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="120" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="184" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="