('5984f026-5f55-565e-ba0d-9a7f911cbea7', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 11, 11, 'A 3.0 µF capacitor is connected in series with a parallel pair of 3.0 µF capacitors. Find the equivalent capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '2', 'µF', false, NULL, false, ARRAY['2e-6']::text[], 'Parallel pair: 6.0 µF. In series with 3.0 µF: C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. Mark scheme (2 marks). C1: parallel pair then series. A1: C = 2.0 µF.', 2, NULL, NULL),
('16f1da41-33a9-50d0-9eed-4bb41f2938a8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 12, 12, 'Three identical capacitors can be connected in four different ways. Which arrangement gives the smallest combined capacitance?', NULL, 1, 'multiple_choice'::answer_type, 'All three in series', NULL, false, NULL, false, NULL, 'All in series gives C/3, the smallest of C/3, 2C/3, 1.5C and 3C. Mark scheme (1 mark). B1: A (All three in series).', 1, NULL, NULL),
('e1c7808d-75b2-5525-96c1-28237744dfa8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 13, 13, 'A network has two 10 µF capacitors in parallel with each other, and also in parallel with a branch made of two 10 µF capacitors in series. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '25', 'µF', false, NULL, false, ARRAY['2.5e-5']::text[], 'Series branch: 10 ÷ 2 = 5.0 µF. Total: 10 + 10 + 5.0 = 25 µF. Mark scheme (2 marks). C1: series branch then add parallel paths. A1: C = 25 µF.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 270 200" role="img" aria-labelledby="fg57501ba7-t fg57501ba7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg57501ba7-t">Capacitor network</title><desc id="fg57501ba7-d">Between A and B: two 10 µF capacitors in parallel, also in parallel with a branch of two 10 µF capacitors in series.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="158" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="184" y2="158" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="115" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="50" x2="184" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="38" x2="115" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-line