('7751db74-250c-5700-b79d-c638b4b9b7d4', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 15, 15, 'Two 1.0 µF capacitors in parallel are connected in series with another two 1.0 µF capacitors in parallel. Calculate the combined capacitance, in µF.', NULL, 1, 'numeric'::answer_type, '1', 'µF', false, NULL, false, ARRAY['1e-6']::text[], 'Each parallel pair is 2.0 µF; two in series give 2.0 ÷ 2 = 1.0 µF. Mark scheme (2 marks). C1: reduce each pair. A1: C = 1.0 µF.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 302 146" role="img" aria-labelledby="fg8988c68b-t fg8988c68b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8988c68b-t">Capacitor network</title><desc id="fg8988c68b-d">Between A and B: two 1.0 µF capacitors in parallel, in series with another two 1.0 µF capacitors in parallel.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="136" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="50" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="83" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="38" x2="83" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="38" x2="93" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 µF</text><line x1="56" y1="104" x2="83" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="104" x2="120" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="92" x2="83" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="92" x2="93" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 µF</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="120" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="136" y1="50" x2="152" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="50" x2="232" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152" y1="50" x2="152" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="216" y1="50" x2="216" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152" y1="50" x2="179" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="189" y1="50" x2="216" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179" y1="38" x2="179" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:ro