ll:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Two series pairs of 10 µF capacitors connected in parallel across 20 V.'),
('2ebcbe51-f385-5a91-b0a3-022b2dad4148', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 33, 33, 'When are two capacitors in a network in series with each other?', NULL, 2, 'multiple_choice'::answer_type, 'When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both', NULL, false, NULL, false, NULL, 'Series requires a single path: the joining node must have no other branch. Mark scheme (4 marks). C1: single junction with no other branch. C1: same charge. C1: drawing position irrelevant. A1: C (When they are joined at a junction to which nothing else is connected, so the same charge must flow onto both).', 4, NULL, NULL),
('e5b5a2ec-5eda-5fcc-8bb2-2f18702d1fa4', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 34, 34, 'Two 1.0 µF capacitors in series are connected in parallel with a 1.0 µF capacitor, and this combination is in series with a 1.5 µF capacitor. Calculate the combined capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '0.75', 'µF', false, NULL, false, ARRAY['7.5e-7']::text[], 'Series pair 0.50 µF; parallel with 1.0 µF gives 1.5 µF; in series with 1.5 µF: 1.5 ÷ 2 = 0.75 µF. Mark scheme (3 marks). C1: inner reductions. C1: final series step. A1: C = 0.75 µF.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 334 146" role="img" aria-labelledby="fgf0ef86a7-t fgf0ef86a7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf0ef86a7-t">Capacitor network</title><desc id="fgf0ef86a7-d">Between A and B: two 1.0 µF capacitors in series, in parallel with a 1.0 µF capacitor, all in series with a 1.5 µF capacitor.</desc><line x1="40" y1="50" x2="56" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="200" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="56" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="184" y1="50" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="50" x2="83" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="50" x2="120" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="38" x2="83" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="38" x2="93" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 µF</text><line x1="120" y1="50" x2="147" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="50" x2="184" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="147" y1="38" x2="147" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="157" y1="38" x2="157" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="152" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 µF</text><line x1="56" y1="104" x2="115" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="104" x2="184" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="115" y1="92" x2="115" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="125" y1="92" x2="125" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="120" y="80" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.0 µF</text><circle cx="56" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="184" cy="50" r="3.2" style="fill:currentColor;stroke:none"/><line x1="200" y1="50" x2="227" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="237" y1="50" x2="264" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="227" y1="38" x2="227" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="237" y1="38" x2="237" y2="62" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232" y="26" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.5 µF</text><line x1="18" y1="50" x2="40" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="18" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="8" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><line x1="286" y1="50" x2="264" y2="50" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="286" cy="50" r="4" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="296" y="38" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B</text></svg>', 'Between A and B: two 1.0 µF capacitors in series, in parallel with a 1.0 µF capacitor, all in series with a 1.5 µF capacitor.'),
('38ad4d90-e392-57df-9a1b-f9372b1d5331', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 35, 35, 'A 4.0 µF capacitor C₁ is in series with a parallel pair C₂ = 2.0 µF and C₃ = 2.0 µF, across a 12 V supply. Calculate the charge on C₂, in µC.', NULL, 2, 'numeric'::answer_type, '12 uC', 'µC', false, NULL, false, NULL, 'Parallel pair 4.0 µF; total C = 2.0 µF; Q = 2.0 × 10⁻⁶ × 12 = 2.4 × 10⁻⁵ C. V₁ = 2.4 × 10⁻⁵ ÷ 4.0 × 10⁻⁶ = 6.0 V, so the pair has 6.0 V. Q₂ = 2.0 × 10⁻⁶ × 6.0 = 1.2 × 10⁻⁵ C. In µC: 1.2 × 10⁻⁵ × 10⁶ = 12. Mark scheme (4 marks). C1: total C. C1: p.d. across C₁. C1: p.d. across pair. C1: Q₂ = C₂V.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fgb445e89f-t fgb445e89f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb445e89f-t">Capacitor network</title><desc id="fgb445e89f-d">C₁ = 4.0 µF in series with C₂ = 2.0 µF and C₃ = 2.0 µF in parallel, across a 12 V supply.</desc><line x1="26" y1="48" x2="75" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="36" x2="75" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="36" x2="85" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₁ = 4.0 µF</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₂ = 2.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₃ = 2.0 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'C₁ = 4.0 µF in series with C₂ = 2.0 µF and C₃ = 2.0 µF in parallel, across a 12 V supply.'),
('3b4cbd57-5d69-5449-868d-691b83ae0fb8', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 36, 36, 'A network is connected across a fixed supply. A new capacitor is connected directly across the supply, in parallel with the whole network. What happens to the charges on the original capacitors?', NULL, 2, 'multiple_choice'::answer_type, 'They stay the same', NULL, false, NULL, false, NULL, 'The p.d. across the original network is still the supply p.d., so its charges are unchanged. Mark scheme (3 marks). C1: p.d. across network unchanged. C1: Q = CV unchanged. A1: A (They stay the same).', 3, NULL, NULL),
('5060c3d2-ec12-5c4e-8adc-03c14942e5df', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 37, 37, 'A 4.7 µF capacitor is connected in parallel with a branch of two 4.7 µF capacitors in series. Calculate the combined capacitance, in µF.', NULL, 2, 'numeric'::answer_type, '7.05', 'µF', false, NULL, false, ARRAY['7.05e-6']::text[], 'Series branch: 4.7 ÷ 2 = 2.35 µF. Total: 4.7 + 2.35 = 7.05 µF. Mark scheme (3 marks). C1: series branch. C1: add parallel. A1: C = 7.05 µF.', 3, NULL, NULL),
('03c4ff30-52f3-5aab-bb85-52ebfdbd59fe', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 38, 38, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V. Calculate the p.d. across the single 3.0 µF capacitor.', NULL, 2, 'numeric'::answer_type, '18', 'V', false, NULL, false, NULL, 'Parallel pair 9.0 µF; total C = 3.0 × 9.0 ÷ 12 = 2.25 µF; Q = 2.25 × 10⁻⁶ × 24 = 5.4 × 10⁻⁵ C. V = 5.4 × 10⁻⁵ ÷ 3.0 × 10⁻⁶ = 18 V. Mark scheme (3 marks). C1: total C. C1: Q = CV. C1: V = Q/C.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg825c27fc-t fg825c27fc-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg825c27fc-t">Capacitor network</title><desc id="fg825c27fc-d">A 3.0 µF capacitor in series with a 6.0 µF and a 3.0 µF capacitor in parallel, across 24 V.</desc><line x1="26" y1="48" x2="75" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="36" x2="75" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="36" x2="85" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">24 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 3.0 µF capacitor in series with a 6.0 µF and a 3.0 µF capacitor in parallel, across 24 V.'),
('22055414-78d8-552c-8d52-c47bba00e49b', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 39, 39, 'One capacitor in a series chain develops a short circuit. What happens to the combined capacitance of the chain?', NULL, 2, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'Removing a term from the reciprocal sum makes 1/C smaller, so C rises. Mark scheme (3 marks). C1: fewer series capacitors. C1: total rises. A1: D (It increases).', 3, NULL, NULL),
('45acf745-704f-5751-9572-62e5e6641adf', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 40, 40, 'A 3.0 µF capacitor is in series with a parallel pair of a 6.0 µF and a 3.0 µF capacitor, across 24 V; the series 3.0 µF capacitor has 18 V across it. Calculate the energy stored in the 6.0 µF capacitor, in µJ.', NULL, 2, 'numeric'::answer_type, '108 uJ', 'µJ', false, NULL, false, NULL, 'p.d. across the parallel pair: 24 − 18 = 6.0 V. W = 0.5 × 6.0 × 10⁻⁶ × 6.0² = 1.08 × 10⁻⁴ J. In µJ: 1.08 × 10⁻⁴ × 10⁶ = 108. Mark scheme (4 marks). C1: p.d. across parallel pair. C1: W = ½CV². C1: conversion. A1: W = 108 µJ.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg957dfe94-t fg957dfe94-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg957dfe94-t">Capacitor network</title><desc id="fg957dfe94-d">A 3.0 µF capacitor in series with a 6.0 µF and a 3.0 µF capacitor in parallel, across 24 V; the series 3.0 µF capacitor has 18 V across it.</desc><line x1="26" y1="48" x2="75" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="36" x2="75" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="36" x2="85" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.0 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">24 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 3.0 µF capacitor in series with a 6.0 µF and a 3.0 µF capacitor in parallel, across 24 V; the series 3.0 µF capacitor has 18 V across it.'),
('79041e4e-f757-599a-994b-deddb9c105d7', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 41, 41, 'Three identical capacitors are connected with two in series and that pair in parallel with the third. The combined capacitance is 6.0 µF. Calculate the capacitance of each, in µF.', NULL, 2, 'numeric'::answer_type, '4', 'µF', false, NULL, false, ARRAY['4e-6']::text[], 'Combined = C/2 + C = 1.5C, so C = 6.0 ÷ 1.5 = 4.0 µF. Mark scheme (3 marks). C1: 1.5C. C1: rearranged. A1: C = 4.0 µF.', 3, NULL, NULL),
('971ea543-29d4-59d8-a0fb-b50f937ceaa1', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 42, 42, 'Four identical capacitors, each C, are to give a combined capacitance of C. Which arrangement does this?', NULL, 2, 'multiple_choice'::answer_type, 'Two series pairs connected in parallel', NULL, false, NULL, false, NULL, 'Each series pair is C/2; two in parallel give C. (Two parallel pairs in series also give C.). Mark scheme (3 marks). C1: series pair C/2. C1: two in parallel give C. A1: B (Two series pairs connected in parallel).', 3, NULL, NULL),
('e8f3b9d0-bab8-517a-9d73-630ce4361798', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 43, 43, 'A 5.0 µF capacitor is connected in parallel with a branch of two 10 µF capacitors in series, across 15 V. Calculate the charge on one of the 10 µF capacitors, in µC.', NULL, 2, 'numeric'::answer_type, '75 uC', 'µC', false, NULL, false, NULL, 'The series branch is 5.0 µF with 15 V across it: Q = 5.0 × 10⁻⁶ × 15 = 7.5 × 10⁻⁵ C on each capacitor in it. In µC: 7.5 × 10⁻⁵ × 10⁶ = 75. Mark scheme (3 marks). C1: branch C = 5.0 µF. C1: Q = CV for the branch. A1: Q = 75 µC.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fgf05883c9-t fgf05883c9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf05883c9-t">Capacitor network</title><desc id="fgf05883c9-d">A 5.0 µF capacitor in parallel with two 10 µF capacitors in series, across 15 V.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="145" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="36" x2="145" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="36" x2="155" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">5.0 µF</text><line x1="42" y1="102" x2="91" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101" y1="102" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="91" y1="90" x2="91" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="101" y1="90" x2="101" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="96" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">15 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 5.0 µF capacitor in parallel with two 10 µF capacitors in series, across 15 V.'),
('5e918ab8-b20a-517d-b94b-63691d57aa94', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 44, 44, 'In a network, C₁ = 2.0 µF and C₂ = 3.0 µF are in parallel; this pair is in series with C₃ = 10 µF; and the whole branch is in parallel with C₄ = 1.0 µF. The network is connected across 12 V. (a) Calculate the combined capacitance. (b) Calculate the total charge drawn from the supply. (c) Calculate the p.d. across C₃. (d) Calculate the charge on C₂, in µC. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '24 uC', 'µC', false, NULL, false, NULL, '(a) C₁ ∥ C₂ = 5.0 µF; with C₃ in series: 5.0 × 10 ÷ 15 = 3.33 µF; plus C₄: 4.33 µF. (b) Q = 4.333 × 12 = 52.0 µC. (c) The series branch has 12 V: Q_branch = 3.333 × 12 = 40 µC, so V₃ = 40 ÷ 10 = 4.0 V. (d) p.d. across the C₁ ∥ C₂ pair: 12 − 4.0 = 8.0 V. Q₂ = 3.0 × 8.0 = 24 µC. Mark scheme (6 marks). C1: inner parallel pair. C1: series with C₃. C1: total C. C1: V₃ from branch charge. C1: Q₂ = C₂V. A1: Q₂ = 24 µC.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 290" role="img" aria-labelledby="fg8ddbe6c8-t fg8ddbe6c8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8ddbe6c8-t">Capacitor network</title><desc id="fg8ddbe6c8-d">C₁ = 2.0 µF and C₂ = 3.0 µF in parallel, in series with C₃ = 10 µF; the whole branch is in parallel with C₄ = 1.0 µF, across 12 V.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="58" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152.1" y1="48" x2="168.1" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="58" y1="48" x2="58" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152.1" y1="48" x2="152.1" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="58" y1="48" x2="100.1" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.1" y1="48" x2="152.1" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100.1" y1="36" x2="100.1" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.1" y1="36" x2="110.1" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="105.1" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₁ = 2.0 µF</text><line x1="58" y1="102" x2="100.1" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.1" y1="102" x2="152.1" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="100.1" y1="90" x2="100.1" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.1" y1="90" x2="110.1" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="105.1" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₂ = 3.0 µF</text><circle cx="58" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="152.1" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="168.1" y1="48" x2="208.1" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="218.1" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="208.1" y1="36" x2="208.1" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="218.1" y1="36" x2="218.1" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="213.1" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₃ = 10 µF</text><line x1="42" y1="156" x2="145" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="156" x2="258" y2="156" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="144" x2="145" y2="168" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="144" x2="155" y2="168" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="132" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₄ = 1.0 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="250" x2="145" y2="250" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="250" x2="274" y2="250" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="237" x2="145" y2="263" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="243" x2="155" y2="257" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 V</text><line x1="26" y1="48" x2="26" y2="250" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="250" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'C₁ = 2.0 µF and C₂ = 3.0 µF in parallel, in series with C₃ = 10 µF; the whole branch is in parallel with C₄ = 1.0 µF, across 12 V.'),
('56b4f545-f8ad-5fcc-afd0-bfdb4741beeb', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 45, 45, 'A 12 µF capacitor is in series with a parallel pair of an 8.0 µF and a 4.0 µF capacitor, across 20 V. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across the parallel pair. (d) Calculate the energy stored in the 8.0 µF capacitor, in mJ. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '0.4 mJ', 'mJ', false, NULL, false, NULL, '(a) Parallel pair 12 µF; with 12 µF in series: C = 12 ÷ 2 = 6.0 µF. (b) Q = 6.0 × 10⁻⁶ × 20 = 1.2 × 10⁻⁴ C. (c) V = 1.2 × 10⁻⁴ ÷ 12 × 10⁻⁶ = 10 V. (d) W = 0.5 × 8.0 × 10⁻⁶ × 10² = 4.0 × 10⁻⁴ J. In mJ: 4.0 × 10⁻⁴ × 1000 = 0.40. Mark scheme (6 marks). C1: parallel pair. C1: series total. C1: Q = CV. C1: p.d. across pair. C1: W = ½CV². A1: W = 0.40 mJ.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fgb9c6a9c1-t fgb9c6a9c1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb9c6a9c1-t">Capacitor network</title><desc id="fgb9c6a9c1-d">A 12 µF capacitor in series with an 8.0 µF and a 4.0 µF capacitor in parallel, across 20 V.</desc><line x1="26" y1="48" x2="75" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="36" x2="75" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="36" x2="85" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12 µF</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.0 µF</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">20 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A 12 µF capacitor in series with an 8.0 µF and a 4.0 µF capacitor in parallel, across 20 V.'),
('430a2382-527a-5ea7-83f9-379635650d1c', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 46, 46, 'Identical 10 µF capacitors rated at 25 V are available. A network is needed that has a combined capacitance of 10 µF and can safely be used at 50 V. (a) Explain why a single capacitor will not do. (b) Describe a suitable network and state how many capacitors it uses. (c) Calculate the energy stored by the network at 50 V, in mJ. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '12.5 mJ', 'mJ', false, NULL, false, NULL, '(a) A single capacitor would have 50 V across it, twice its rating. (b) Two series pairs connected in parallel: four capacitors; each pair shares 50 V as 25 V each, and gives 5.0 µF, so the two pairs give 10 µF. (c) W = 0.5 × 10 × 10⁻⁶ × 50² = 0.0125 J. In mJ: 0.0125 × 1000 = 12.5. Mark scheme (5 marks). B1: rating exceeded. B1: two series pairs in parallel. C1: four capacitors, 25 V each. C1: W = ½CV². A1: W = 12.5 mJ.', 5, NULL, NULL),
('ffdfffc6-e72d-5e5b-bd08-125b4c7e5083', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 47, 47, 'A 4.0 µF capacitor C₁ is charged to 12 V and disconnected. It is then connected across a series pair of uncharged capacitors, C₂ = 6.0 µF and C₃ = 3.0 µF. (a) Calculate the capacitance of the series pair. (b) Calculate the final p.d. across C₁. (c) Calculate the final p.d. across C₃. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '8', 'V', false, NULL, false, NULL, '(a) C = 6.0 × 3.0 ÷ 9.0 = 2.0 µF. (b) Charge 4.0 × 12 = 48 µC is shared between C₁ and the 2.0 µF pair in parallel: V = 48 ÷ (4.0 + 2.0) = 8.0 V. (c) The pair carries 2.0 × 8.0 = 16 µC, so V₃ = 16 ÷ 3.0 = 5.3 V. Mark scheme (6 marks). C1: series pair. M1: charge conserved. C1: shared over 6.0 µF. C1: charge on pair. C1: V₃. A1: V = 8.0 V.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 182" role="img" aria-labelledby="fg2ec717c2-t fg2ec717c2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2ec717c2-t">Charge sharing with a series pair</title><desc id="fg2ec717c2-d">C₁ = 4.0 µF, charged to 12 V, is connected through a switch across a series pair of uncharged capacitors C₂ = 6.0 µF and C₃ = 3.0 µF.</desc><line x1="26" y1="48" x2="98.8" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="108.8" y1="48" x2="181.6" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="98.8" y1="36" x2="98.8" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="108.8" y1="36" x2="108.8" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="103.8" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₁ = 4.0 µF, 12 V</text><line x1="181.6" y1="48" x2="213.8" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="241.8" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="213.8" cy="48" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="241.8" cy="48" r="2.6" style="fill:currentColor;stroke:none"/><line x1="213.8" y1="48" x2="239.8" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="142" x2="83" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="142" x2="150" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="130" x2="83" y2="154" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="130" x2="93" y2="154" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="88" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₂ = 6.0 µF</text><line x1="150" y1="142" x2="207" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="142" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="207" y1="130" x2="207" y2="154" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="217" y1="130" x2="217" y2="154" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="212" y="166" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₃ = 3.0 µF</text><line x1="26" y1="48" x2="26" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="142" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'C₁ = 4.0 µF, charged to 12 V, is connected through a switch across a series pair of uncharged capacitors C₂ = 6.0 µF and C₃ = 3.0 µF.'),
('5a26f93e-4536-5148-9729-7232bbdadb09', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 48, 48, 'An unknown capacitor X is connected in series with a 4.7 µF capacitor, and a meter shows a combined capacitance of 3.1 µF. (a) Calculate X, in µF. (b) Capacitors have a tolerance of ±10 %. Explain how this affects your confidence in the value of X. Give only the answer to (a).', NULL, 3, 'numeric'::answer_type, '9.106', 'µF', false, NULL, false, ARRAY['9.106e-6']::text[], '(a) 1/X = 1/3.1 − 1/4.7, so X = 1 ÷ (1/3.1 − 1/4.7) = 9.11 µF. (b) A small change in the 4.7 µF value makes a large change in the difference of reciprocals, so X is quite uncertain. Mark scheme (5 marks). M1: reciprocal rule rearranged. C1: substitution. C1: value. B1: uncertainty amplified by subtraction. A1: X = 9.11 µF.', 5, NULL, NULL),
('bd47d583-6475-5380-9f7c-9cc58ccccbed', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 49, 49, 'A 3.0 µF capacitor C₁ is in series with a parallel pair of a 2.0 µF capacitor C₂ and an unknown capacitor C₃. The network is connected to a 10 V supply, and the p.d. across C₁ is 6.0 V. (a) Calculate the charge on C₁. (b) Calculate the p.d. across the parallel pair. (c) Calculate C₃, in µF. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '2.5', 'µF', false, NULL, false, ARRAY['2.5e-6']::text[], '(a) Q = 3.0 × 10⁻⁶ × 6.0 = 1.8 × 10⁻⁵ C. (b) 10 − 6.0 = 4.0 V. (c) The pair carries 1.8 × 10⁻⁵ C at 4.0 V, so C₂ + C₃ = 1.8 × 10⁻⁵ ÷ 4.0 = 4.5 × 10⁻⁶ F. C₃ = 4.5 − 2.0 = 2.5 µF. Mark scheme (6 marks). C1: Q = CV. C1: p.d.s add. M1: same charge on pair as on C₁. C1: pair capacitance. C1: subtract C₂. A1: C₃ = 2.5 µF.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 236" role="img" aria-labelledby="fg6fdf9c82-t fg6fdf9c82-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6fdf9c82-t">Capacitor network</title><desc id="fg6fdf9c82-d">C₁ = 3.0 µF in series with C₂ = 2.0 µF and an unknown C₃ in parallel, across a 10 V supply; C₁ has 6.0 V across it.</desc><line x1="26" y1="48" x2="75" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="48" x2="134" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="75" y1="36" x2="75" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="85" y1="36" x2="85" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="80" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₁ = 3.0 µF</text><line x1="134" y1="48" x2="150" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="274" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="150" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258" y1="48" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="48" x2="199" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="48" x2="258" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="36" x2="199" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="36" x2="209" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₂ = 2.0 µF</text><line x1="150" y1="102" x2="199" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="102" x2="258" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="199" y1="90" x2="199" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209" y1="90" x2="209" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="204" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₃</text><circle cx="150" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="258" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="26" y1="196" x2="145" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="196" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="145" y1="183" x2="145" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="155" y1="189" x2="155" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="150" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="48" x2="274" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'C₁ = 3.0 µF in series with C₂ = 2.0 µF and an unknown C₃ in parallel, across a 10 V supply; C₁ has 6.0 V across it.'),
('f5f62353-df52-5e76-b310-3057d07bb4e3', '34322ed1-8148-406d-97ee-947a4eca6b7f', 'c4c09cba-9d0a-4033-abe7-0b8c56bb7ef4', 'a-level', '23.6', '9702 coursebook 23.6 · Capacitor networks', 50, 50, 'In a network, C₁ = 6.0 µF is in series with C₂ = 3.0 µF; this pair is in parallel with C₃ = 4.0 µF; and the whole block is in series with C₄ = 12 µF. The network is connected to a 24 V supply. (a) Calculate the combined capacitance. (b) Calculate the charge drawn from the supply. (c) Calculate the p.d. across C₄ and across the block. (d) Calculate the p.d. across C₁. (e) Calculate the total energy stored. Give only the answer to (d).', NULL, 3, 'numeric'::answer_type, '5.333', 'V', false, NULL, false, NULL, '(a) C₁, C₂ in series: 2.0 µF; with C₃: 6.0 µF; with C₄ in series: 6.0 × 12 ÷ 18 = 4.0 µF. (b) Q = 4.0 × 24 = 96 µC. (c) V₄ = 96 ÷ 12 = 8.0 V; block: 24 − 8.0 = 16 V. (d) The C₁–C₂ branch carries 2.0 × 16 = 32 µC, so V₁ = 32 ÷ 6.0 = 5.33 V. (e) W = 0.5 × 4.0 × 10⁻⁶ × 24² = 0.00115 J. Mark scheme (7 marks). C1: series pair. C1: block. C1: total C. C1: Q and V₄. M1: branch charge from block p.d. C1: total energy. A1: V₁ = 5.33 V.', 7, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 348.7 236" role="img" aria-labelledby="fg46b5340a-t fg46b5340a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg46b5340a-t">Capacitor network</title><desc id="fg46b5340a-d">C₁ = 6.0 µF in series with C₂ = 3.0 µF; this pair in parallel with C₃ = 4.0 µF; the block in series with C₄ = 12 µF, across a 24 V supply.</desc><line x1="26" y1="48" x2="42" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.3" y1="48" x2="237.3" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="42" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="221.3" y1="48" x2="221.3" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="42" y1="48" x2="81.8" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="91.8" y1="48" x2="131.6" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="81.8" y1="36" x2="81.8" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="91.8" y1="36" x2="91.8" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="86.8" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₁ = 6.0 µF</text><line x1="131.6" y1="48" x2="171.5" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="181.5" y1="48" x2="221.3" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="171.5" y1="36" x2="171.5" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="181.5" y1="36" x2="181.5" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="176.5" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₂ = 3.0 µF</text><line x1="42" y1="102" x2="126.6" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136.6" y1="102" x2="221.3" y2="102" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="126.6" y1="90" x2="126.6" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="136.6" y1="90" x2="136.6" y2="114" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="131.6" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₃ = 4.0 µF</text><circle cx="42" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><circle cx="221.3" cy="48" r="3.2" style="fill:currentColor;stroke:none"/><line x1="237.3" y1="48" x2="275" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285" y1="48" x2="322.7" y2="48" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="275" y1="36" x2="275" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="285" y1="36" x2="285" y2="60" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="280" y="24" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">C₄ = 12 µF</text><line x1="26" y1="196" x2="169.4" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.4" y1="196" x2="322.7" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="169.4" y1="183" x2="169.4" y2="209" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.4" y1="189" x2="179.4" y2="203" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="174.4" y="220" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">24 V</text><line x1="26" y1="48" x2="26" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="322.7" y1="48" x2="322.7" y2="196" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'C₁ = 6.0 µF in series with C₂ = 3.0 µF; this pair in parallel with C₃ = 4.0 µF; the block in series with C₄ = 12 µF, across a 24 V supply.')
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('6096145b-f638-5d22-9826-d19ebe98ef0d', 'a65123eb-042f-5495-9153-1df7a1aaffba', 'Add all the capacitances together', 'A', false, 0),
('e6e7637d-79a2-5fab-b104-e74b3620f40e', 'a65123eb-042f-5495-9153-1df7a1aaffba', 'Use the reciprocal rule for every capacitor', 'B', false, 1),
('4cf39902-9293-5a0a-be65-1bad127e37a8', 'a65123eb-042f-5495-9153-1df7a1aaffba', 'Replace each group that is clearly in series or clearly in parallel with a single equivalent capacitor', 'C', true, 2),
('29b7eddc-e82c-506c-b5c5-9cf1d0d47c82', 'a65123eb-042f-5495-9153-1df7a1aaffba', 'Start with the capacitor nearest the positive terminal', 'D', false, 3),
('17d023d0-cad5-52e6-bee5-268b46fb3a16', '16f1da41-33a9-50d0-9eed-4bb41f2938a8', 'All three in series', 'A', true, 0),
('77ff3dc2-56bf-51d4-9a33-4e87d051547f', '16f1da41-33a9-50d0-9eed-4bb41f2938a8', 'All three in parallel', 'B', false, 1),
