INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('96e990fc-60b8-585e-9f4f-8280e5a7c51b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 6, 6, 'A charged capacitor discharges through a resistor. Which describes the graph of current against time?', NULL, 1, 'multiple_choice'::answer_type, 'An exponential decay curve', NULL, false, NULL, false, NULL, 'I = I₀e^(−t/RC): the current falls by the same fraction in each equal time interval. Mark scheme (1 mark). B1: C (An exponential decay curve).', 1, NULL, NULL),
('448a39ac-197b-5a27-b291-70601f552069', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 7, 7, 'A 2200 µF capacitor discharges through a 1.0 kΩ resistor. Calculate the time constant.', NULL, 1, 'numeric'::answer_type, '2.2', 's', false, NULL, false, NULL, 'τ = RC = 1000 × 2200 × 10⁻⁶ = 2.2 s. Mark scheme (2 marks). C1: τ = RC. A1: τ = 2.2 s.', 2, NULL, NULL),
('55e5e9e0-7c6b-5852-b12f-c82be5a2ce4d', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 8, 8, 'What is the time constant of a discharging capacitor circuit?', NULL, 1, 'multiple_choice'::answer_type, 'The time for the charge to fall to 1/e (about 37 %) of its initial value', NULL, false, NULL, false, NULL, 'At t = RC, Q = Q₀e⁻¹ ≈ 0.37Q₀. Mark scheme (1 mark). B1: A (The time for the charge to fall to 1/e (about 37 %) of its initial value).', 1, NULL, NULL),
('6000d6d0-f400-562b-bf36-b2411354e536', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 9, 9, 'What fraction of its initial charge remains on a discharging capacitor after two time constants?', NULL, 1, 'numeric'::answer_type, '0.1353', NULL, false, NULL, false, NULL, 'Q/Q₀ = e^(−2) = 0.135. Mark scheme (2 marks). C1: Q/Q₀ = e^(−t/RC). A1: fraction = 0.135.', 2, NULL, NULL),
('4666562e-5ca0-5e8e-bcdc-8390eeaffb5a', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 10, 10, 'The instant a capacitor charged to 6.0 V begins discharging through a 1.5 kΩ resistor, what current flows, in mA?', NULL, 1, 'numeric'::answer_type, '4 mA', 'mA', false, NULL, false, NULL, 'I₀ = V₀/R = 6.0 ÷ 1500 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (2 marks). C1: I₀ = V₀/R. A1: I₀ = 4.0 mA.', 2, NULL, NULL),
('9582fc07-8f53-5456-8993-427088d63c0e', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 11, 11, 'The resistance through which a capacitor discharges is increased. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'The capacitor discharges more slowly', NULL, false, NULL, false, NULL, 'τ = RC increases, so the decay is slower. Mark scheme (1 mark). B1: D (The capacitor discharges more slowly).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 158" role="img" aria-labelledby="fgaed563b5-t fgaed563b5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgaed563b5-t">Discharge circuit</title><desc id="fgaed563b5-d">A charged capacitor connected through a switch across a resistor.</desc><line x1="26" y1="36" x2="83" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="36" x2="150" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="83" y1="24" x2="83" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93" y1="24" x2="93" y2="48" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="36" x2="198" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="226" y1="36" x2="274" y2="36" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="198" cy="36" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="226" cy="36" r="2.6" style="fill:currentColor;stroke:none"/><line x1="198" y1="36" x2="224" y2="24" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="118" x2="132" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="168" y1="118" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="132" y="111" width="36" height="14" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="26" y1="36" x2="26" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="274" y1="36" x2="274" y2="118" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A charged capacitor connected through a switch across a resistor.'),
('85fae43e-ef5d-5fcd-a3b1-2a01d1cc88e0', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 12, 12, 'A capacitor initially holds 4.0 mC. Calculate the charge remaining after one time constant, in mC.', NULL, 1, 'numeric'::answer_type, '1.472 mC', 'mC', false, NULL, false, NULL, 'Q = Q₀e^(−1) = 4.0 × e^(−1) = 1.47 mC. Mark scheme (2 marks). C1: Q = Q₀e⁻¹. A1: Q = 1.47 mC.', 2, NULL, NULL),
('1fb4f9e3-b3f5-5e2e-a17c-8b3c7d43091c', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 13, 13, 'What is the unit of the product RC?', NULL, 1, 'multiple_choice'::answer_type, 's', NULL, false, NULL, false, NULL, 'Ω × F = (V A⁻¹)(C V⁻¹) = C A⁻¹ = s. Mark scheme (1 mark). B1: B (s).', 1, NULL, NULL),
('7c09f2d6-c225-5157-9408-86c9413125a3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 14, 14, 'A 47 µF capacitor in a sensor circuit drains through a 220 kΩ resistor. What is RC for this circuit?', NULL, 1, 'numeric'::answer_type, '10.34', 's', false, NULL, false, NULL, 'τ = RC = 220 × 10³ × 47 × 10⁻⁶ = 10.3 s. Mark scheme (2 marks). C1: τ = RC with prefixes converted. A1: τ = 10.3 s.', 2, NULL, NULL),
('e50ce724-5e25-5b03-8c52-7f3d89614e7b', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 15, 15, 'For a discharging capacitor, what does a graph of ln(V) against t look like?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line with gradient −1/RC', NULL, false, NULL, false, NULL, 'V = V₀e^(−t/RC) gives ln V = ln V₀ − t/RC. Mark scheme (1 mark). B1: C (A straight line with gradient −1/RC).', 1, NULL, NULL),
('26369a4d-3f5f-5284-82cf-592683d1a7d2', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 16, 16, 'A discharge circuit has a time constant of 5.0 s. Calculate the time for the charge to halve.', NULL, 1, 'numeric'::answer_type, '3.466', 's', false, NULL, false, NULL, 't½ = RC ln 2 = 5.0 × ln 2 = 3.47 s. Mark scheme (2 marks). C1: t½ = RC ln 2. A1: t½ = 3.47 s.', 2, NULL, NULL),
('a360e909-dabf-57fc-9abd-e95fbe4cc8a3', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 17, 17, 'In each 2.0 s interval, a discharging capacitor loses 30 % of the charge it had at the start of that interval. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'The discharge is exponential', NULL, false, NULL, false, NULL, 'Losing a constant fraction in equal time intervals is the property of exponential decay. Mark scheme (1 mark). B1: A (The discharge is exponential).', 1, NULL, NULL),
('98689426-aa36-5e02-b0b3-ee5fa2bb69f1', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 18, 18, 'Engineers often treat a capacitor as fully discharged after 5RC. What fraction of its charge is actually left then?', NULL, 1, 'numeric'::answer_type, '0.006738', NULL, false, NULL, false, NULL, 'Q/Q₀ = e^(−5) = 0.00674. Mark scheme (1 mark). A1: fraction = 0.00674.', 1, NULL, NULL),
('06a7d94b-57dd-5026-8d4d-a00cb2fcde3f', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 19, 19, 'During the discharge of a capacitor through a resistor, how do the current and the p.d. across the capacitor change?', NULL, 1, 'multiple_choice'::answer_type, 'Both decay exponentially with the same time constant', NULL, false, NULL, false, NULL, 'I = V/R at every instant, so both follow e^(−t/RC). Mark scheme (1 mark). B1: D (Both decay exponentially with the same time constant).', 1, NULL, NULL),
('f16f53e8-1573-5960-9b34-31c9dbcc8640', '34322ed1-8148-406d-97ee-947a4eca6b7f', '0c42a207-4bd1-5379-b11d-d983544be962', 'a-level', '23.7', '9702 coursebook 23.7 · Discharging a capacitor', 20, 20, 'A 470 µF capacitor charged to 9.0 V discharges through a 10 kΩ resistor. Calculate the p.d. across it after 3.0 s.', NULL, 2, 'numeric'::answer_type, '4.754', 'V', false, NULL, false, NULL, 'RC = 10 × 10³ × 470 × 10⁻⁶ = 4.7 s. V = 9.0 × e^(−3.0/4.7) = 4.75 V. Mark scheme (3 marks). C1: RC. C1: V = V₀e^(−t/RC). A1: V = 4.75 V.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg70ea5b56-t fg70ea5b56-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg70ea5b56-t">Discharge curve</title><desc id="fg70ea5b56-d">Graph of p.d. against time for a 470 µF capacitor discharging from 9.0 V through 10 kΩ (time constant 4.7 s). A dashed line marks t = 3.0 s.</desc><line x1="39.8" y1="34" x2="39.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="108.2" y1="34" x2="108.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="176.7" y1="34" x2="176.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="245.1" y1="34" x2="245.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="313.6" y1="34" x2="313.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="39.8" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1