ke-linecap:round;stroke-linejoin:round"/><text x="297" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10.5</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">14.0</text><line x1="38.2" y1="242" x2="42.2" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="35.2" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="38.2" y1="195.6" x2="42.2" y2="195.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="35.2" y="195.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">V₀/4</text><line x1="38.2" y1="149.1" x2="42.2" y2="149.1" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="35.2" y="149.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">V₀/2</text><line x1="38.2" y1="56.3" x2="42.2" y2="56.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="35.2" y="56.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">V₀</text><text x="212.1" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">t / s</text><text x="38.2" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V</text><polyline points="42.2,56.3 43,57.6 43.9,58.8 44.7,60.1 45.6,61.4 46.4,62.6 47.3,63.9 48.1,65.1 49,66.3 49.8,67.5 50.7,68.7 51.5,69.9 52.4,71.1 53.2,72.3 54.1,73.5 54.9,74.6 55.8,75.8 56.6,76.9 57.5,78.1 58.3,79.2 59.2,80.3 60,81.4 60.9,82.6 61.7,83.7 62.6,84.7